(function(){'use strict';
/* JAH The Number Theory Signature generator — jahdb-number-theory-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-NUMTHS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Number Theory", "desc": "Number theory studies the integers - the oldest mathematics (Babylonian triples, Euclid's Elements Book VII-IX) and among the deepest. Gauss called it the queen of mathematics (Disquisitiones, 1801).\nElementary (divisibility, primes - Euclid's tools), analytic (complex analysis counts primes - Riemann), algebraic (ideals, fields - Kummer to Wiles). Pure for millennia, then suddenly practical: cryptography made primes worth billions.", "how": "Start with integers and divisibility; prove (induction, contradiction); compute (Euclid's algorithm by hand). Graduate: analytic (generating functions) and algebraic (rings) perspectives. Always test conjectures computationally first.", "keys": ["The integers: oldest and deepest.", "Gauss: queen of mathematics (1801).", "Elementary, analytic, algebraic faces.", "Pure for millennia; now secures the internet.", "Prove; compute; conjecture."], "reqs": ["Integer domain stated.", "Proof method chosen.", "Computational check."], "stds": ["ℕ, ℤ notation.", "Proofs complete."], "cites": ["Gauss CF. Disquisitiones Arithmeticae. 1801.", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"First primes.\"\"\"\ndef primes(n):\n    s = [True]*(n+1)\n    for i in range(2, int(n**0.5)+1):\n        if s[i]: s[i*i::i] = [False]*len(s[i*i::i])\n    return [i for i in range(2, n+1) if s[i]]\nprint(\" \", primes(30))\n"}, {"tier": "Foundations", "g": "Divisibility", "title": "Divisibility and the Division Algorithm", "desc": "a|b: exists c with b = ac. Division algorithm: a = qb + r (0 ≤ r < b) - the foundation of all computation with integers. Properties: transitivity, linear combinations (d|a and d|b → d|(ax+by) - Bézout's identity).\nBézout: gcd(a,b) = smallest positive combination - the key to inverses, Diophantine equations, RSA key generation. Everything flows from division with remainder.", "how": "Test divisibility (factor or modular); apply division algorithm (quotient + remainder); form linear combinations for gcd. Use Bézout to find inverses and solve ax+by = gcd. Prove divisibility facts via the algorithm.", "keys": ["a|b: b = ac.", "Division: a = qb + r.", "Bézout: gcd as combination.", "Linear combinations preserve divisibility.", "Foundation of integer computation."], "reqs": ["Divisor non-zero.", "Remainder range (0 ≤ r < b).", "Bézout coefficients."], "stds": ["a|b notation.", "Division with 0 ≤ r < b."], "cites": ["Euclid. Elements, Books VII-IX.", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Bézout coefficients (extended Euclid).\"\"\"\ndef xgcd(a, b):\n    return (a, 1, 0) if b == 0 else (lambda g, x1, y1: (g, y1, x1-(a//b)*y1))(*xgcd(b, a % b))\ng, x, y = xgcd(48, 18)\nprint(f\"  gcd= {g}; {x}*48 + {y}*18 = {x*48+y*18}\")\n"}, {"tier": "Foundations", "g": "Divisibility", "title": "The Euclidean Algorithm", "desc": "gcd(a,b) = gcd(b, a mod b), repeated - 2,300 years old and still the fastest way (logarithmic steps). Extended version gives Bézout coefficients (x, y with ax+by = gcd) - modular inverses, RSA keys, Diophantine solutions.\nLamé's theorem: steps ≤ 5× digits (Fibonacci pairs are worst case). The algorithm that never died - from Euclid's Elements to every crypto library.", "how": "Run Euclid (repeated remainders); extend for coefficients (back-substitution or iterative). Use for: gcd, inverses (mod n), simplifying fractions, solving linear Diophantine. Count steps (worst: consecutive Fibonacci).", "keys": ["gcd(a,b) = gcd(b, a mod b).", "2,300 years old; still fastest.", "Extended: Bézout coefficients.", "Logarithmic steps.", "Fibonacci: worst case."], "reqs": ["Inputs positive integers.", "Termination (remainder 0).", "Coefficients (extended)."], "stds": ["gcd(a,b) notation.", "Steps counted."], "cites": ["Euclid. Elements, Book VII.", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Euclid trace: gcd(1071, 462).\"\"\"\ndef euclid(a, b):\n    steps = 0\n    while b:\n        a, b, steps = b, a % b, steps+1\n    return a, steps\nprint(\"  gcd, steps:\", euclid(1071, 462))\n"}, {"tier": "Foundations", "g": "Primes", "title": "Prime Numbers: Introduction", "desc": "Primes: divisible only by 1 and self - the atoms of multiplication. Euclid proved infinitely many (c. 300 BCE): multiply known primes, add 1, find a new prime factor - the most beautiful proof in mathematics.\nPrimality testing (deterministic: AKS 2002; practical: Miller-Rabin), prime gaps, twin primes (unproven infinite). Largest known: Mersenne primes (2^p - 1, GIMPS finds them - 2^82,589,933-1 in 2018, 24M digits).", "how": "Test small primes (trial division to √n); use Miller-Rabin for large. Prove infinitude (Euclid's argument); explore gaps computationally. Hunt Mersennes (Lucas-Lehmer test) via GIMPS.", "keys": ["Atoms of multiplication.", "Euclid: infinitely many (~300 BCE).", "Miller-Rabin: practical testing.", "Mersenne primes: largest known.", "Twin primes: open."], "reqs": ["Primality test method.", "Proof of infinitude understood.", "Size/complexity noted."], "stds": ["Primes as p, q.", "Tests named (Miller-Rabin)."], "cites": ["Euclid. Elements, Book IX, Prop. 20.", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Miller-Rabin (deterministic for n < 2^64 with these bases).\"\"\"\ndef is_prime(n):\n    if n < 2: return False\n    for p in (2,3,5,7,11,13):\n        if n % p == 0: return n == p\n    d, s = n-1, 0\n    while d % 2 == 0: d, s = d//2, s+1\n    import random\n    for a in (2, 325, 9375, 28178, 450775, 9780504, 1795265022):\n        if a % n == 0: continue\n        x = pow(a, d, n)\n        if x in (1, n-1): continue\n        if any(pow(a, d*2**r, n) == n-1 for r in range(s-1)): continue\n        return False\n    return True\nprint(\"  104729 prime:\", is_prime(104729), \"| 104730:\", is_prime(104730))\n"}, {"tier": "Foundations", "g": "Primes", "title": "The Fundamental Theorem of Arithmetic", "desc": "Every integer > 1 factors uniquely into primes (existence: strong induction; uniqueness: Euclid's lemma - p|ab → p|a or p|b). The basis of all multiplicative number theory - without uniqueness, nothing works.\nConsequences: divisor formulas (count, sum from exponents), gcd/lcm via min/max exponents, rational roots of polynomials. Non-uniqueness elsewhere (ℤ[√-5]) motivated ideal theory - the theorem's failure birthed algebraic number theory.", "how": "Factor integers (trial division/Fermat); verify uniqueness (assume two factorizations, derive contradiction via Euclid's lemma). Compute divisor counts/sums from exponents. Contrast with non-UFDs (ℤ[√-5]).", "keys": ["Unique prime factorization.", "Euclid's lemma: p|ab → p|a or p|b.", "Divisor formulas from exponents.", "Failure elsewhere → ideals.", "Basis of multiplicative theory."], "reqs": ["Factorization.", "Uniqueness argument.", "Exponent bookkeeping."], "stds": ["n = Π p_i^{e_i}.", "Euclid's lemma cited."], "cites": ["Euclid. Elements, Book VII.", "Gauss CF. Disquisitiones Arithmeticae. 1801."], "demo": "#!/usr/bin/env python3\n\"\"\"Divisor count/sum from exponents.\"\"\"\ndef tau_sigma(n):\n    fac, d = {}, 2\n    while d*d <= n:\n        while n % d == 0: fac[d] = fac.get(d, 0)+1; n //= d\n        d += 1\n    if n > 1: fac[n] = 1\n    from functools import reduce\n    import operator\n    tau = reduce(operator.mul, (e+1 for e in fac.values()), 1)\n    return tau, fac\nprint(\"  360:\", tau_sigma(360), \"-> 24 divisors\")\n"}, {"tier": "Foundations", "g": "Congruences", "title": "Congruences: Introduction", "desc": "a ≡ b (mod m): m divides a-b - arithmetic on remainders. Gauss's Disquisitiones (1801) made it systematic. Operations respect congruence (add, multiply freely); division needs coprime modulus (inverses).\nApplications: checksums (ISBN-10: weighted sum ≡ 0 mod 11), calendars (mod 7), hashing. The language of cyclic phenomena - clocks, weeks, cryptography.", "how": "Reduce mod m (least residues); verify operations preserve congruence; find inverses (extended Euclid, when gcd = 1). Solve linear congruences (ax ≡ b). Apply to checksums and calendars.", "keys": ["a ≡ b (mod m): same remainder.", "Gauss 1801: systematic.", "Add/multiply freely; divide carefully.", "Inverses need coprime modulus.", "Clocks, checksums, crypto."], "reqs": ["Modulus stated.", "Residue system.", "Coprimality for inverses."], "stds": ["a ≡ b (mod m).", "Least residues 0..m-1."], "cites": ["Gauss CF. Disquisitiones Arithmeticae. 1801.", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"ISBN-10 check digit.\"\"\"\ndef isbn10_ok(digits):\n    return sum((10-i)*d for i, d in enumerate(digits)) % 11 == 0\nprint(\"  0306406152 valid:\", isbn10_ok([0,3,0,6,4,0,6,1,5,2]))\n"}, {"tier": "Foundations", "g": "Congruences", "title": "Fermat's Little Theorem", "desc": "a^{p-1} ≡ 1 (mod p) for prime p, a not divisible by p - Fermat 1640. Corollary: a^p ≡ a (mod p) always. Proof via permutations of residues (multiply 1..p-1 by a).\nPowers RSA: encryption exponents reduce mod p-1. Primality testing: base-a Fermat test (Carmichael numbers fool it - 561 = 3·11·17 passes all bases coprime to it). Euler's theorem generalizes (a^{φ(n)} ≡ 1 mod n).", "how": "Verify for small primes (compute powers); apply to reduce exponents (mod p-1); test primality (Fermat test - note Carmichael caveat). Generalize to Euler (composite moduli). Use in RSA correctness.", "keys": ["a^{p-1} ≡ 1 (mod p).", "Fermat 1640.", "Reduces exponents (RSA).", "Carmichael numbers fool the test.", "Euler generalizes to φ(n)."], "reqs": ["p prime verified.", "a not divisible by p.", "Carmichael caveat noted."], "stds": ["Theorem stated exactly.", "φ(n) for Euler."], "cites": ["Fermat P. (1640, letter to Frenicle).", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Fermat check + Carmichael trap.\"\"\"\nprint(\"  2^10 mod 11 =\", pow(2, 10, 11), \"(=1, prime)\")\nprint(\"  2^560 mod 561 =\", pow(2, 560, 561), \"(=1 but 561 composite: Carmichael!)\")\n"}, {"tier": "Foundations", "g": "Diophantine", "title": "Diophantine Equations: Introduction", "desc": "Integer solutions to polynomial equations - Diophantus's Arithmetica (c. 250 CE). Linear (ax+by = c: solvable iff gcd(a,b)|c - Bézout), Pythagorean (x²+y² = z²: parametrized by Euclid's formula), exponential (Ramanujan-Nagell).\nHilbert's 10th problem (1970, Matiyasevich): no general algorithm decides solvability - undecidable. From linear (easy) to general (impossible): the full complexity spectrum.", "how": "Solve linear (Bézout/gcd test); parametrize Pythagorean (m²-n², 2mn, m²+n²); test solvability mod n (obstructions). Note undecidability for general - restrict to tractable families.", "keys": ["Integer solutions sought.", "Diophantus c. 250 CE.", "Linear: gcd test.", "Pythagorean: Euclid's parametrization.", "Hilbert 10th: undecidable (1970)."], "reqs": ["Equation + integer domain.", "Solvability test.", "Parametrization where known."], "stds": ["Solutions as integer tuples.", "gcd conditions stated."], "cites": ["Diophantus. Arithmetica. c. 250.", "Matiyasevich Y. (Hilbert 10th, 1970)."], "demo": "#!/usr/bin/env python3\n\"\"\"Pythagorean triples via Euclid formula.\"\"\"\ndef triples(limit_m):\n    out = []\n    for m in range(2, limit_m+1):\n        for n in range(1, m):\n            out.append((m*m-n*n, 2*m*n, m*m+n*n))\n    return out\nprint(\" \", triples(4)[:3])\n"}, {"tier": "Foundations", "g": "Functions", "title": "Arithmetic Functions", "desc": "Functions on integers with number-theoretic meaning: d(n) (divisor count), σ(n) (divisor sum), φ(n) (Euler's totient - count coprime ≤ n), μ(n) (Möbius - inclusion-exclusion on primes). Multiplicative: f(mn) = f(m)f(n) for coprime - determined by prime powers.\nφ(p^k) = p^k - p^{k-1}; RSA uses φ(pq) = (p-1)(q-1). Dirichlet convolution (*) unifies them (μ * 1 = ε - Möbius inversion). Perfect numbers: σ(n) = 2n (Euclid-Euler characterization for even).", "how": "Compute from prime factorization (multiplicativity); evaluate φ (RSA's key quantity); apply Möbius inversion (sums over divisors). Test perfection (σ(n) = 2n); search Mersenne-linked even perfects.", "keys": ["d, σ, φ, μ: the core functions.", "Multiplicative: prime powers determine.", "φ(pq) = (p-1)(q-1) (RSA).", "Möbius inversion.", "Perfect: σ(n) = 2n."], "reqs": ["Factorization.", "Multiplicativity verified.", "Formula per function."], "stds": ["φ(n), μ(n), σ(n) notation.", "Dirichlet convolution *."], "cites": ["Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008.", "Apostol TM. Introduction to Analytic Number Theory. Springer; 1976."], "demo": "#!/usr/bin/env python3\n\"\"\"Euler totient.\"\"\"\ndef phi(n):\n    r, p = n, 2\n    while p*p <= n:\n        if n % p == 0:\n            while n % p == 0: n //= p\n            r -= r//p\n        p += 1\n    return r - r//n if n > 1 else r\nprint(\"  φ(36) =\", phi(36), \"(= 36·(1-1/2)·(1-1/3))\")\n"}, {"tier": "Foundations", "g": "Proof", "title": "Proof Techniques in Number Theory", "desc": "The toolkit: induction (statements for all n), infinite descent (Fermat's favorite - smaller solution → contradiction), contradiction (Euclid's primes, √2 irrational), pigeonhole (two numbers share a remainder), constructive (Euclid's algorithm).\nStyle: precise quantifiers, cases complete, minimal counterexample. Number theory's proofs are often short but deep - descent proving √2 irrational in lines, FLT(n=4) via infinite descent.", "how": "Choose method by shape (all-n → induction; impossibility → descent/contradiction). Write completely (base case, quantifiers); check edge cases (n=0,1). Study model proofs (Euclid IX.20, √2 irrational).", "keys": ["Induction, descent, contradiction.", "Pigeonhole: shared remainders.", "Fermat's infinite descent.", "Minimal counterexample.", "Short but deep."], "reqs": ["Method chosen deliberately.", "Quantifiers precise.", "Edge cases checked."], "stds": ["Proofs end with ∎/QED.", "Cases exhaustive."], "cites": ["Fermat P. (Descent, n=4 FLT).", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Pigeonhole: among n+1 integers, two share a remainder mod n.\"\"\"\ndef find_pair(nums, n):\n    seen = {}\n    for x in nums:\n        r = x % n\n        if r in seen: return (seen[r], x)\n        seen[r] = x\nprint(\"  pair:\", find_pair([3, 7, 11, 15, 22], 4))\n"}, {"tier": "Foundations", "g": "History", "title": "History: From Euclid to Wiles", "desc": "300 BCE Euclid (primes, algorithm); 250 CE Diophantus; 1637 Fermat's margin (FLT); 1801 Gauss's Disquisitiones (modern subject); 1859 Riemann hypothesis; 1847-1995 FLT saga (Kummer's ideals → Wiles's modularity proof); 1977 RSA (primes go practical).\nThe arc: recreational → systematic → deep → applied. Amateurs (Fermat the lawyer, Mersenne the monk) drove it for centuries - the most democratic branch of mathematics.", "how": "Trace: Euclid → Diophantus → Fermat → Euler → Gauss → Riemann → 20th century. Note amateur contributions; connect each era's tools to its theorems. Read Weil's history for the human story.", "keys": ["Euclid: primes + algorithm.", "Fermat 1637: the margin note.", "Gauss 1801: modern subject.", "Riemann 1859: the hypothesis.", "Wiles 1995: FLT proved."], "reqs": ["Timeline accuracy.", "Primary sources cited.", "Era-tool connections."], "stds": ["Dates with results.", "Names spelled correctly."], "cites": ["Weil A. Number Theory: An Approach Through History. Birkhäuser; 1984.", "Singh S. Fermat's Enigma. Walker; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Number theory timeline.\"\"\"\nfor y, e in [(-300, \"Euclid\"), (250, \"Diophantus\"), (1637, \"Fermat FLT\"), (1801, \"Gauss\"), (1859, \"Riemann\"), (1995, \"Wiles\")]:\n    print(f\"  {y}: {e}\")\n"}, {"tier": "Compounded", "g": "Congruences", "title": "Solving Congruences", "desc": "Linear: ax ≡ b (mod m) solvable iff gcd(a,m)|b - divide through, invert. Systems: Chinese Remainder Theorem (moduli coprime → unique solution mod product; constructive via Garner) - Sunzi (3rd century), Qin Jiushao (1247).\nPolynomial: Hensel's lemma lifts simple roots mod p to mod p^k (p-adic Newton). Quadratic congruences → quadratic reciprocity (below). Congruences are equations - solve them systematically.", "how": "Solve linear (gcd test → reduce → invert); combine systems (CRT - Garner for computation); lift with Hensel (check derivative non-zero mod p). Verify solutions by substitution.", "keys": ["Linear: gcd test.", "CRT: combine coprime moduli.", "Sunzi 3rd c.; Qin 1247.", "Hensel lifts roots.", "Verify by substitution."], "reqs": ["Modulus/moduli.", "Coprimality (CRT).", "Solution verification."], "stds": ["Solutions mod m.", "CRT isomorphism stated."], "cites": ["Sunzi Suanjing (3rd c.).", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"CRT: x=2 mod 3, x=3 mod 5, x=2 mod 7.\"\"\"\ndef crt(rems, mods):\n    from functools import reduce\n    M = reduce(lambda a, b: a*b, mods)\n    x = 0\n    for r, m in zip(rems, mods):\n        Mi = M//m\n        x += r*Mi*pow(Mi, -1, m)\n    return x % M\nprint(\"  x =\", crt([2, 3, 2], [3, 5, 7]), \"(mod 105)\")\n"}, {"tier": "Compounded", "g": "Congruences", "title": "Quadratic Reciprocity", "desc": "Gauss's golden theorem: (p/q)(q/p) = (-1)^((p-1)(q-1)/4) - whether p is a quadratic residue mod q relates to q mod p. Legendre symbol (a/p): 1 (residue), -1 (non), 0 (divisible); Euler's criterion: (a/p) ≡ a^{(p-1)/2}.\nGauss gave 6+ proofs; 200+ exist. It computes: is 2 a square mod p? (yes iff p ≡ ±1 mod 8). The prototype of reciprocity laws - class field theory's ancestor.", "how": "Evaluate Legendre symbols (Euler's criterion for small; reciprocity to flip and reduce for large); determine residuosity. Apply to: square roots mod p (Tonelli-Shanks), primality (Euler pseudoprimes), crypto (Goldwasser-Micali).", "keys": ["(p/q)(q/p) = (-1)^((p-1)(q-1)/4).", "Gauss's golden theorem.", "Legendre: 1/-1/0.", "Euler's criterion computes.", "Prototype of reciprocity."], "reqs": ["Odd primes distinct.", "Legendre evaluation.", "Supplement laws (±1, 2)."], "stds": ["(a/p) notation.", "Reciprocity stated exactly."], "cites": ["Gauss CF. Disquisitiones Arithmeticae. 1801.", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Is 2 a quadratic residue mod p? (supplement).\"\"\"\ndef is2res(p):\n    return p % 8 in (1, 7)\nfor p in (7, 11, 17, 23):\n    print(f\"  p={p}: {\"residue\" if is2res(p) else \"non-residue\"}\")\n"}, {"tier": "Compounded", "g": "Primes", "title": "Prime Distribution", "desc": "π(x) ~ x/ln x: the Prime Number Theorem (Hadamard/de la Vallée Poussin 1896, via Riemann's zeta) - primes thin logarithmically. Gaps average ln x; maximal gaps grow (prime gaps project). Twin primes: Zhang (2013, gaps ≤ 70M) → Polymath (≤ 246).\nRiemann Hypothesis (1859): all non-trivial zeta zeros on Re(s) = 1/2 - the $1M Clay problem governing prime error terms. Chebyshev: 0.92 x/ln x < π(x) < 1.11 x/ln x (elementary bounds).", "how": "Estimate π(x) (x/ln x); compute exactly (Meissel-Lehmer); analyze gaps computationally. State RH precisely; note what's conditional on it. Use explicit bounds (Rosser-Schoenfeld) for rigorous work.", "keys": ["π(x) ~ x/ln x (PNT 1896).", "Gaps average ln x.", "RH: zeros on critical line ($1M).", "Zhang/Polymath: bounded gaps.", "Chebyshev's elementary bounds."], "reqs": ["x range.", "Estimate vs exact.", "Conditionality noted."], "stds": ["π(x) notation.", "Asymptotics with ~."], "cites": ["Hadamard J, de la Vallée Poussin CJB. (PNT, 1896).", "Riemann B. (1859)."], "demo": "#!/usr/bin/env python3\n\"\"\"PNT estimate vs actual.\"\"\"\nimport math\ndef pi_small(n):\n    s = [True]*(n+1)\n    for i in range(2, int(n**0.5)+1):\n        if s[i]: s[i*i::i] = [False]*len(s[i*i::i])\n    return sum(s[2:])\nfor n in (100, 1000):\n    print(f\"  π({n}) = {pi_small(n)}; n/ln n = {n/math.log(n):.1f}\")\n"}, {"tier": "Compounded", "g": "Primes", "title": "Primality Testing", "desc": "Trial division (to √n - only for small), Fermat (Carmichael fools), Miller-Rabin (probabilistic - error 4^{-k}; deterministic for n < 2⁶⁴ with known bases), Lucas, AKS (2002: polynomial-time deterministic - theoretical breakthrough, impractical).\nPractice: Miller-Rabin with enough rounds (cryptographic: 64+ rounds or deterministic bases). Prime generation: random odd + Miller-Rabin (RSA keygen). Proving primality (ECPP) for records.", "how": "Choose test by need (Miller-Rabin practical; AKS theoretical; ECPP for proofs). Set rounds for target error (4^{-k}); use deterministic bases below 2⁶⁴. Generate primes (random + test); never use untested 'primes' in crypto.", "keys": ["Miller-Rabin: practical.", "AKS 2002: polynomial deterministic.", "Error 4^{-k} per round.", "Deterministic below 2⁶⁴.", "ECPP proves primality."], "reqs": ["Test method.", "Error bound.", "Size regime."], "stds": ["Rounds stated.", "Bases for deterministic."], "cites": ["Agrawal M et al. Ann Math 2004;160:781-793 (AKS).", "Rabin MO. J Number Theory 1980;12:128-138."], "demo": "#!/usr/bin/env python3\n\"\"\"Miller-Rabin error bound.\"\"\"\nfor k in (1, 10, 40, 64):\n    print(f\"  {k:2d} rounds: error ≤ 4^-{k} ≈ {4.0**-k:.0e}\")\n"}, {"tier": "Compounded", "g": "Diophantine", "title": "Pythagorean Triples and Fermat's Last Theorem (Introduction)", "desc": "x²+y² = z²: Euclid's parametrization (m²-n², 2mn, m²+n²) gives all primitive triples - complete solution. FLT: xⁿ+yⁿ = zⁿ has no positive integer solutions for n > 2 - Fermat 1637, proved Wiles 1995 (modularity of elliptic curves).\nThe saga: Sophie Germain (case 1), Kummer (regular primes via ideals), Frey-Hellegouarch curve (link to Taniyama-Shimura), Wiles + Taylor (1995). 358 years, all of modern number theory - one margin note's legacy.", "how": "Generate triples (Euclid's formula); prove completeness (descent). Trace FLT: understand n=4 (Fermat's descent) before Wiles. State modularity (every elliptic curve is modular) as the key. Read Singh for the human story.", "keys": ["Euclid parametrizes triples.", "FLT: no solutions n > 2.", "1637 → 1995 (358 years).", "Wiles: modularity.", "Kummer's ideals; Germain's cases."], "reqs": ["n specified.", "Primitive vs non-primitive.", "Proof era stated."], "stds": ["Triples (a,b,c).", "FLT stated exactly."], "cites": ["Wiles A. Ann Math 1995;141:443-551.", "Singh S. Fermat's Enigma. Walker; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Fermat n=4 idea (infinite descent).\"\"\"\nprint(\"  x^4+y^4=z^4 -> right triangle with square sides\")\nprint(\"  descent: smaller solution exists -> infinite descent -> impossible\")\n"}, {"tier": "Compounded", "g": "Crypto", "title": "RSA: How It Works", "desc": "Keygen: pick large primes p, q; n = pq; φ = (p-1)(q-1); choose e coprime to φ; d = e⁻¹ mod φ. Encrypt: c = m^e mod n; decrypt: m = c^d mod n - correctness via Euler's theorem. Security: factoring n recovers φ (hard for 2048-bit).\nRivest-Shamir-Adleman 1977 (GCHQ's Ellis/Cocks earlier, classified). Padding (OAEP) required - textbook RSA is insecure (deterministic, malleable). Quantum (Shor) breaks it - post-quantum migration underway.", "how": "Implement toy RSA (small primes - NEVER real sizes by hand); encrypt/decrypt (pow with mod); verify correctness (Euler). Use OAEP padding conceptually; key sizes ≥ 2048 real. Note quantum threat (Shor).", "keys": ["n = pq; e·d ≡ 1 mod φ(n).", "Euler's theorem: correctness.", "Security = factoring hardness.", "1977 (GCHQ earlier, secret).", "Padding required; Shor threatens."], "reqs": ["Prime sizes.", "Padding scheme.", "Toy-vs-real disclaimer."], "stds": ["Key sizes in bits.", "e = 65537 standard."], "cites": ["Rivest R et al. Commun ACM 1978;21:120-126.", "Shor PW. (1994, quantum factoring)."], "demo": "#!/usr/bin/env python3\n\"\"\"Toy RSA (insecure sizes - demo only).\"\"\"\np, q, e = 61, 53, 17\nn, phi = p*q, (p-1)*(q-1)\nd = pow(e, -1, phi)\nfor m in (42, 1234):\n    c = pow(m, e, n)\n    print(f\"  m={m}: encrypt -> {c}, decrypt -> {pow(c, d, n)}\")\n"}, {"tier": "Compounded", "g": "Crypto", "title": "Diffie-Hellman and Discrete Logs", "desc": "Key exchange: agree prime p, generator g; Alice picks a, sends g^a; Bob picks b, sends g^b; shared secret g^{ab} - eavesdropper faces discrete log (recover a from g^a). Diffie-Hellman 1976: public-key cryptography's birth.\nSecurity: discrete log hard in F_p^* (index calculus subexponential - need 2048+ bits) and elliptic curves (fully exponential - 256 bits suffice). Man-in-the-middle needs authentication (signatures). Forward secrecy via ephemeral keys.", "how": "Run toy DH (small p - demo only); compute shared secrets both ways; verify equality. Explain discrete-log hardness (vs easy exponentiation); size parameters (2048-bit F_p, 256-bit ECC). Authenticate to prevent MITM.", "keys": ["Shared secret g^{ab}.", "Security: discrete log.", "1976: public-key born.", "ECC: 256 bits suffice.", "Authenticate (MITM defense)."], "reqs": ["Group + generator.", "Parameter sizes.", "Authentication."], "stds": ["p in bits.", "Generator g specified."], "cites": ["Diffie W, Hellman M. IEEE Trans Inf Theory 1976;22:644-654.", "Shor PW. (1994)."], "demo": "#!/usr/bin/env python3\n\"\"\"Toy Diffie-Hellman (demo only).\"\"\"\np, g = 23, 5\na, b = 6, 15\nA, B = pow(g, a, p), pow(g, b, p)\nprint(f\"  Alice sends {A}, Bob sends {B}\")\nprint(f\"  shared: {pow(B, a, p)} = {pow(A, b, p)}\")\n"}, {"tier": "Compounded", "g": "Continued Fractions", "title": "Continued Fractions", "desc": "Every real = [a₀; a₁, a₂, ...] (Euclid's algorithm on reals): rationals terminate, quadratics repeat (Lagrange), others don't. Convergents p_k/q_k are best approximations (|α - p/q| < 1/q² - Dirichlet; Hurwitz: 1/√5 q² infinitely often).\nApplications: calendar design (leap years), gear ratios (Antikythera), RSA attacks (Wiener's: small private exponent via convergents), solving Pell equations (period length). The most underrated tool in number theory.", "how": "Expand (floor, invert, repeat); compute convergents (recurrence); find best approximations. Solve Pell (period of √D); attack small-d RSA (Wiener). Design calendars/gears via convergents.", "keys": ["[a₀; a₁, a₂, ...].", "Rationals terminate; quadratics repeat.", "Convergents: best approximations.", "Pell equations via periods.", "Wiener attacks small-d RSA."], "reqs": ["Expansion computed.", "Convergents listed.", "Approximation quality."], "stds": ["[a0; a1, ...] notation.", "Convergents p_k/q_k."], "cites": ["Lagrange JL. (Periodic = quadratic).", "Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008."], "demo": "#!/usr/bin/env python3\n\"\"\"Continued fraction of pi.\"\"\"\ndef cf(x, n):\n    out = []\n    for _ in range(n):\n        a = int(x)\n        out.append(a)\n        x = 1/(x-a) if x != a else 0\n        if x == 0: break\n    return out\nprint(\"  π =\", cf(3.14159265358979, 6), \"(355/113 lurks here)\")\n"}, {"tier": "Compounded", "g": "Diophantine", "title": "Pell Equations", "desc": "x² - Dy² = 1 (D non-square): always infinitely many solutions - fundamental solution from continued-fraction period of √D; all from powers (x₁ + y₁√D)ⁿ. Archimedes's cattle problem: D = 4729494 (solution has 206,545 digits!).\nNegative Pell (x² - Dy² = -1): solvable iff period odd. Generalized (x² - Dy² = N): finite solutions per N. Units in ℤ[√D] - the algebraic meaning (Dirichlet's unit theorem).", "how": "Expand √D (period length); convergent at period-1 gives fundamental solution (check); generate all via powers. Test negative Pell (period parity). Connect to units (norm 1 elements).", "keys": ["x² - Dy² = 1: infinite solutions.", "Fundamental from √D period.", "All: powers of fundamental.", "Cattle problem: 206,545 digits.", "Units of norm 1."], "reqs": ["D non-square positive.", "Period computed.", "Fundamental verified."], "stds": ["Solutions (x, y).", "Period length stated."], "cites": ["Hardy GH, Wright EM. An Introduction to the Theory of Numbers. 6th ed. Oxford; 2008.", "Fermat P. (Pell challenges, 1657)."], "demo": "#!/usr/bin/env python3\n\"\"\"Fundamental solution of x^2 - 2y^2 = 1.\"\"\"\ndef min_pell(D, ymax=100000):\n    y = 1\n    while y <= ymax:\n        x2 = 1 + D*y*y\n        x = int(x2**0.5)\n        if x*x == x2: return (x, y)\n        y += 1\n    return None\nprint(\"  D=2:\", min_pell(2))\nprint(\"  D=61: (1766319049, 226153980) - Fermat\\u0027s challenge, found via continued fractions\")\n"}, {"tier": "Compounded", "g": "Sums", "title": "Sums of Squares", "desc": "Which n = x² + y²? Fermat: prime p = x²+y² iff p = 2 or p ≡ 1 mod 4 (descent proof; constructive via Wilson/Hermite). General: n's prime factors ≡ 3 mod 4 need even exponents.\nFour squares: Lagrange (1770) - every natural number (Waring's problem generalizes: g(2) = 4). Two squares theorem in ℤ[i] (norms multiply - Gaussian integers prove Fermat elegantly). Sum-of-two-squares in crypto (Cornacchia).", "how": "Test p ≡ 1 mod 4 (find representation: Cornacchia's algorithm); factor n (check 3-mod-4 exponents). Prove via ℤ[i] (norm multiplicativity, unique factorization). Apply Lagrange for four squares (constructive algorithms exist).", "keys": ["p = x²+y² iff p ≡ 1 mod 4.", "3-mod-4 primes need even exponents.", "Lagrange: four squares always.", "ℤ[i] proves Fermat elegantly.", "Waring generalizes."], "reqs": ["n factored.", "3-mod-4 exponent check.", "Representation found."], "stds": ["Representations (x, y).", "Norms N(a+bi)."], "cites": ["Fermat P. (Two squares, 1640).", "Lagrange JL. (Four squares, 1770)."], "demo": "#!/usr/bin/env python3\n\"\"\"Two-square representations.\"\"\"\ndef two_sq(n):\n    return [(x, int((n-x*x)**0.5)) for x in range(int(n**0.5)+1) if int((n-x*x)**0.5)**2 == n-x*x]\nfor n in (65, 25, 21):\n    print(f\"  {n}: {two_sq(n) if two_sq(n) else \"impossible (3 mod 4 factor)\"}\")\n"}, {"tier": "Compounded", "g": "Elliptic", "title": "Elliptic Curves (Introduction)", "desc": "y² = x³ + ax + b: points form a group (chord-and-tangent) - the group law is geometric. Rank (independent infinite-order points) is mysterious (BSD conjecture, $1M); torsion classified (Mazur).\nCrypto: ECDH/ECDSA (256-bit ≈ 3072-bit RSA); Bitcoin's secp256k1. FLT: Frey curves linked to modular forms (Wiles). Congruent numbers (which n are triangle areas?) - 2,300-year-old problem via curves.", "how": "Plot real points (components); add geometrically (chord-tangent); compute rank (descent/Sage); find torsion (Mazur's list). Use for ECDH (toy); state BSD precisely. Reduce mod p (point counting: Hasse bound).", "keys": ["Points form a group.", "Chord-and-tangent law.", "Rank: mysterious (BSD $1M).", "ECDH: 256-bit security.", "Wiles: curves → FLT."], "reqs": ["Curve equation.", "Discriminant non-zero.", "Group law stated."], "stds": ["y² = x³+ax+b.", "Rank/torsion."], "cites": ["Wiles A. Ann Math 1995;141:443-551.", "Silverman JH. The Arithmetic of Elliptic Curves. Springer; 2009."], "demo": "#!/usr/bin/env python3\n\"\"\"Point doubling on y^2 = x^3 - x (toy).\"\"\"\nprint(\"  P=(2,√6)... use mod 7: points (0,0),(1,0),(6,0),(2,±3),(3,±2),(4,±2),(5,±3)\")\nprint(\"  group law: chord-tangent, computed mod p\")\n"}, {"tier": "Compounded", "g": "Zeta", "title": "The Riemann Zeta Function (Introduction)", "desc": "ζ(s) = Σ 1/n^s: Euler product (primes ↔ zeta), analytic continuation (Riemann 1859), functional equation (s ↔ 1-s), trivial zeros (-2, -4, ...), non-trivial in the critical strip. RH: all on Re(s) = 1/2.\nWhy it matters: explicit formula (primes from zeros - von Mangoldt), error terms in PNT, 10¹³ zeros verified on the line. The deepest object in mathematics - analysis encoding arithmetic.", "how": "Compute ζ (real s > 1: series; elsewhere: functional equation/software); verify Euler product numerically; locate zeros (software). State RH precisely; note equivalences (Mertens, Lagarias). Never claim proof.", "keys": ["ζ(s) = Σ 1/n^s.", "Euler product: primes ↔ zeta.", "Riemann 1859: continuation + RH.", "Functional equation s ↔ 1-s.", "Explicit formula: zeros → primes."], "reqs": ["s domain stated.", "Continuation acknowledged.", "RH stated precisely."], "stds": ["ζ(s) notation.", "Zeros as ρ = β + iγ."], "cites": ["Riemann B. Monatsberichte Akad Berlin 1859.", "Edwards HM. Riemann's Zeta Function. Dover; 1974."], "demo": "#!/usr/bin/env python3\n\"\"\"Euler product converges to zeta(2)=π²/6.\"\"\"\ndef zeta2_euler(nprimes):\n    s, p, count = 1.0, 2, 0\n    while count < nprimes:\n        is_p = all(p % d for d in range(2, int(p**0.5)+1))\n        if is_p:\n            s *= 1/(1-1/p**2); count += 1\n        p += 1\n    return s\nimport math\nprint(f\"  1000 primes: {zeta2_euler(1000):.6f} vs π²/6 = {math.pi**2/6:.6f}\")\n"}, {"tier": "Advanced", "g": "Analytic", "title": "Analytic Number Theory", "desc": "Complex analysis counts integers: Dirichlet series (Σ aₙ/n^s), Euler products, Perron's formula (extract coefficients), contour integration (PNT's proof). Dirichlet (1837): primes in arithmetic progressions (L-functions, non-vanishing at 1).\nTools: sieve methods (Brun, Selberg - bounded gaps), circle method (Hardy-Littlewood - Waring, Goldbach weak proved 2013 Helfgott), exponential sums (Weil bounds). The paradigm: encode arithmetic in analysis, extract via complex integration.", "how": "Form Dirichlet series for the problem; identify poles (PNT: ζ's pole at 1); shift contours (zero-free regions). Apply sieves (upper/lower bounds); use circle method for additive problems. State results with error terms.", "keys": ["Analysis counts integers.", "Dirichlet 1837: primes in progressions.", "PNT via ζ's pole.", "Sieves bound; circle method adds.", "Error terms are the game."], "reqs": ["Dirichlet series.", "Analytic properties.", "Error terms."], "stds": ["O/o notation.", "s = σ + it."], "cites": ["Dirichlet PGL. (1837).", "Apostol TM. Introduction to Analytic Number Theory. Springer; 1976."], "demo": "#!/usr/bin/env python3\n\"\"\"Dirichlet: primes ≡ 3 mod 4 (infinite).\"\"\"\ndef primes_mod(n, a, m):\n    s = [True]*(n+1)\n    for i in range(2, int(n**0.5)+1):\n        if s[i]: s[i*i::i] = [False]*len(s[i*i::i])\n    return [i for i in range(2, n+1) if s[i] and i % m == a % m]\nprint(\" \", primes_mod(50, 3, 4)[:8], \"... (infinite per Dirichlet)\")\n"}, {"tier": "Advanced", "g": "Algebraic", "title": "Algebraic Number Theory (Introduction)", "desc": "Ideals restore unique factorization: rings of integers (𝒪_K), Dedekind domains (ideals factor uniquely), class group (measures failure - class number 1 = UFD), units (Dirichlet's theorem: rank r₁+r₂-1).\nRamification (primes splitting: inert/split/ramify), Frobenius elements, class field theory (abelian extensions classified). Kummer's ideal theory attacked FLT; Hilbert's Zahlbericht (1897) systematized. Arithmetic as geometry - schemes complete the picture.", "how": "Compute rings of integers (integral closure); factor ideals (Dedekind-Kummer); compute class numbers (Minkowski bound); find units (fundamental). Trace ramification (discriminant). Use Sage/PARI for computation.", "keys": ["Ideals factor uniquely.", "Class group measures failure.", "Dirichlet's unit theorem.", "Ramification: splitting types.", "Kummer → Hilbert → class fields."], "reqs": ["Number field K.", "Ring of integers.", "Discriminant."], "stds": ["𝒪_K notation.", "Class number h_K."], "cites": ["Hilbert D. Zahlbericht. 1897.", "Marcus DA. Number Fields. Springer; 1977."], "demo": "#!/usr/bin/env python3\n\"\"\"Norm in Q(i): multiplicativity.\"\"\"\ndef N(z):\n    return int(z.real**2+z.imag**2)\na, b = complex(2,1), complex(1,3)\nprint(f\"  N({a})N({b}) = {N(a)*N(b)} = N({a*b}) = {N(a*b)}\")\n"}, {"tier": "Advanced", "g": "Diophantine", "title": "Fermat's Last Theorem: The Proof", "desc": "Wiles (1995): every semistable elliptic curve over ℚ is modular (Taniyama-Shimura) → Frey's curve (from a^p+b^p = c^p) cannot exist → FLT. Taylor-Wiles patched the gap (1994); Breuil-Conrad-Diamond-Taylor completed full modularity (2001).\nIngredients: Galois representations, Hecke algebras, R=T theorems, Langlands program (modularity is one case). The proof created modern arithmetic geometry - FLT was the excuse, the Langlands program the real prize.", "how": "Understand the chain (Frey curve → non-modular → contradiction); state modularity precisely (Galois representations from curves match modular forms). Follow Ribet's level-lowering (Frey → level 2, impossible). Read Darmon's surveys for the architecture.", "keys": ["Modularity → FLT.", "Frey curve: the bridge.", "Ribet: level-lowering.", "Taylor-Wiles: R=T.", "Langlands: the real prize."], "reqs": ["Frey curve construction.", "Modularity statement.", "Contradiction chain."], "stds": ["E: y² = x(x-a^p)(x+b^p).", "Modular forms S_2(Γ_0(N))."], "cites": ["Wiles A. Ann Math 1995;141:443-551.", "Taylor R, Wiles A. Ann Math 1995;141:553-572."], "demo": "#!/usr/bin/env python3\n\"\"\"FLT: verified to huge bounds (computational).\"\"\"\nprint(\"  checked: no solutions for n ≤ 2.5e6 (Buhler et al.)\")\nprint(\"  proof: modularity (Wiles 1995), not computation\")\n"}, {"tier": "Advanced", "g": "Modular", "title": "Modular Forms (Introduction)", "desc": "Holomorphic functions on the upper half-plane with transformation laws (f((az+b)/(cz+d)) = (cz+d)^k f(z)) - SL(2,ℤ) symmetry. Fourier expansions (q-series: Δ = q Π(1-qⁿ)²⁴); Hecke operators (eigenforms); L-functions.\nModularity: elliptic curves ↔ weight-2 forms (Wiles). Moonshine: j-function coefficients = Monster dimensions (Borcherds, Fields 1998). Partitions (Ramanujan's congruences), sphere packing (Viazovska's magic functions). Symmetry's analytic face.", "how": "Verify transformation laws (generators S, T); compute q-expansions (first terms); apply Hecke operators (eigenvalues). State modularity (curve ↔ form matching L-functions). Explore moonshine numerically (j coefficients).", "keys": ["SL(2,ℤ) symmetry.", "q-expansions.", "Hecke eigenforms.", "Modularity: curves ↔ forms.", "Moonshine: j ↔ Monster."], "reqs": ["Domain (upper half-plane).", "Transformation law.", "Fourier coefficients."], "stds": ["Weight k; level N.", "q = e^{2πiz}."], "cites": ["Serre JP. A Course in Arithmetic. Springer; 1973.", "Diamond F, Shurman J. A First Course in Modular Forms. Springer; 2005."], "demo": "#!/usr/bin/env python3\n\"\"\"j-function first coefficients (moonshine).\"\"\"\n# j = q^-1 + 744 + 196884q + ...; 196884 = 196883 + 1 (Monster!)\nprint(\"  j = 1/q + 744 + 196884q + ...\")\nprint(\"  196884 = 196883 + 1: Monster dimension + trivial\")\n"}, {"tier": "Advanced", "g": "Elliptic", "title": "Elliptic Curves: Arithmetic", "desc": "Mordell-Weil: E(ℚ) ≅ T × ℤ^r (finitely generated) - rank r is the mystery (BSD: rank = order of vanishing of L(E,s) at 1 - $1M). Torsion classified (Mazur's 15 groups). Descent computes ranks (2-descent via isogeny).\nHeegner points (Gross-Zagier: rank 1 cases), parity conjecture, average ranks (Bhargava: < 1). Congruent numbers: n is congruent iff rank(E_n) > 0 (Tunnell conditional on BSD). Arithmetic's central object.", "how": "Compute rank (2-descent/Sage mwrank); find generators (Heegner for rank 1); classify torsion (Mazur). State BSD precisely (regulator, Sha, Tamagawa in the formula). Test congruent numbers (Tunnell's criterion).", "keys": ["Mordell-Weil: finite generation.", "BSD: rank = analytic rank ($1M).", "Mazur: torsion classified.", "Descent computes.", "Congruent numbers via rank."], "reqs": ["Minimal model.", "Rank computation.", "Torsion identification."], "stds": ["E(ℚ) ≅ T × ℤ^r.", "BSD formula terms."], "cites": ["Silverman JH. The Arithmetic of Elliptic Curves. Springer; 2009.", "Bhargava M. (Average ranks)."], "demo": "#!/usr/bin/env python3\n\"\"\"Rank example: y^2 = x^3 - 2 (rank 1).\"\"\"\nprint(\"  generator: (3, 5); torsion: trivial\")\nprint(\"  multiples n·(3,5) give infinite rational points\")\n"}, {"tier": "Advanced", "g": "Crypto", "title": "Elliptic-Curve Cryptography", "desc": "ECDH/ECDSA: group E(F_p), generator G; private d, public dG - discrete log hard (fully exponential - Pollard rho √n; 256-bit ≈ 128-bit security). secp256k1 (Bitcoin), Curve25519 (Bernstein - fast, safe).\nECDSA: sign with nonce k (Sony's PS3 reused k - private keys leaked!); EdDSA (deterministic nonces - safer). Pairings (Weil/Tate) enable BLS signatures, zk-SNARKs. Quantum (Shor) breaks ECC too - PQC migration.", "how": "Implement toy ECDH (small curve); sign/verify ECDSA (test vectors); NEVER reuse nonces (PS3 lesson). Choose curves (25519/448, not suspicious seeds); validate points (on-curve check). Plan PQC migration.", "keys": ["dG: public from private.", "256-bit ≈ 128-bit security.", "Nonce reuse leaks keys (PS3).", "Curve25519: fast + safe.", "Pairings: BLS, zk-SNARKs."], "reqs": ["Curve + field.", "Point validation.", "Nonce discipline."], "stds": ["secp256k1/Curve25519.", "Keys in bits."], "cites": ["Miller V, Koblitz N. (ECC, 1985).", "Bernstein DJ. (Curve25519, 2006)."], "demo": "#!/usr/bin/env python3\n\"\"\"Toy ECDH on tiny curve (demo only).\"\"\"\n# y^2 = x^3 + 2x + 2 mod 17, G=(5,1), order 19\np, G, n = 17, (5, 1), 19\ndef add(P, Q):\n    if P is None: return Q\n    if Q is None: return P\n    x1, y1, x2, y2 = *P, *Q\n    if x1 == x2 and (y1+y2) % p == 0: return None\n    m = ((3*x1*x1+2)*pow(2*y1, -1, p)) % p if P == Q else ((y2-y1)*pow(x2-x1, -1, p)) % p\n    x3 = (m*m-x1-x2) % p\n    return (x3, (m*(x1-x3)-y1) % p)\ndef mul(k, P):\n    R = None\n    while k:\n        if k & 1: R = add(R, P)\n        P, k = add(P, P), k >> 1\n    return R\na, b = 7, 11\nprint(f\"  shared secret: {mul(a, mul(b, G))} = {mul(b, mul(a, G))}\")\n"}, {"tier": "Advanced", "g": "Crypto", "title": "Post-Quantum Cryptography", "desc": "Shor breaks RSA/ECC/DH (quantum factoring/discrete-log) - harvest-now-decrypt-later threatens today's ciphertext. NIST PQC standards (2024): CRYSTALS-Kyber (lattices, key exchange), Dilithium (lattices, signatures), SPHINCS+ (hash-based).\nHard problems: lattices (LWE/SIS - worst-case to average-case), codes (McEliece 1978 - still unbroken), hashes, isogenies (SIKE broken 2022 - cautionary tale), multivariate. Migration: hybrid (classical + PQC) now; larger keys/signatures than ECC.", "how": "Inventory quantum-vulnerable crypto (RSA, ECC, DH); pilot NIST standards (Kyber/Dilithium via liboqs); go hybrid during transition. Size parameters (Kyber-768: ~2400-byte public keys). Track NIST rounds; avoid broken (SIKE).", "keys": ["Shor breaks RSA/ECC/DH.", "NIST 2024: Kyber, Dilithium, SPHINCS+.", "Lattices: worst-case hardness.", "McEliece 1978: still standing.", "Hybrid migration now."], "reqs": ["Vulnerable inventory.", "NIST standard choice.", "Hybrid plan."], "stds": ["NIST levels (1-5).", "Key/signature sizes."], "cites": ["NIST FIPS 203/204/205 (2024).", "Shor PW. (1994)."], "demo": "#!/usr/bin/env python3\n\"\"\"PQC key sizes vs ECC.\"\"\"\nfor alg, pk in [(\"ECC P-256\", 64), (\"Kyber-768\", 1184), (\"Dilithium-3\", 1952), (\"SPHINCS+\", 32)]:\n    print(f\"  {alg:13s}: public key ~{pk} bytes\")\n"}, {"tier": "Advanced", "g": "Open", "title": "Open Problems", "desc": "Riemann Hypothesis (1859, $1M): zeros on the critical line - 10¹³ verified, proof elusive. Goldbach (1742): every even > 2 is two primes (weak proved 2013). Twin primes infinite? (bounded gaps ≤ 246). Collatz (1937): 3n+1 always reaches 1.\nBSD ($1M), abc (Mochizuki's claimed proof - unverified), Beal, Legendre's (prime between n² and (n+1)²), Landau's 4 problems. Number theory: easy to ask, hard to answer - the field's signature.", "how": "State each precisely (what's known, what's open); verify computationally to bounds; note conditional results (what RH/BSD would imply). Never claim proofs; report verifications honestly. Tackle via: computation, conditional proof, partial progress.", "keys": ["RH: $1M, 10¹³ zeros verified.", "Goldbach: weak proved 2013.", "Twin primes: gaps ≤ 246.", "Collatz: 3n+1.", "Easy to ask, hard to answer."], "reqs": ["Precise statement.", "Known bounds.", "Conditional implications."], "stds": ["Conjectures labeled as such.", "Verification bounds stated."], "cites": ["Riemann B. (1859).", "Clay Mathematics Institute (Millennium Problems)."], "demo": "#!/usr/bin/env python3\n\"\"\"Collatz test to 10000.\"\"\"\ndef collatz(n):\n    while n != 1: n = n//2 if n % 2 == 0 else 3*n+1\n    return True\nprint(\"  all n ≤ 10000 reach 1:\", all(collatz(n) for n in range(1, 10001)))\n"}, {"tier": "Advanced", "g": "Transcendence", "title": "Transcendental Numbers", "desc": "Transcendental: not algebraic (no integer-polynomial root) - Liouville (1844, first explicit: Σ 10^{-n!}), Hermite (e, 1873), Lindemann (π, 1882 - Weierstrass generalized: Lindemann-Weierstrass). Almost all reals are transcendental (Cantor: algebraics countable).\nOpen: π+e, πe, γ (Euler-Mascheroni), Catalan's G - transcendence unknown. Gelfond-Schneider (1934): a^b transcendental (a algebraic ≠ 0,1; b algebraic irrational) - settled Hilbert's 7th. Schanuel's conjecture would unify.", "how": "Prove transcendence (Lindemann-Weierstrass for e/π; Gelfond-Schneider for powers); note open cases honestly. Use: e^π transcendental (Gelfond-Schneider). Count (Cantor's argument: almost all transcendental).", "keys": ["Not algebraic.", "Liouville 1844: first explicit.", "e (1873), π (1882).", "Almost all reals transcendental.", "π+e: open."], "reqs": ["Algebraicity test.", "Theorem applied.", "Open cases labeled."], "stds": ["Transcendence proofs cited.", "Open problems flagged."], "cites": ["Lindemann F. Math Ann 1882;20:213-225.", "Baker A. Transcendental Number Theory. Cambridge; 1975."], "demo": "#!/usr/bin/env python3\n\"\"\"Liouville number (transcendental).\"\"\"\nL = sum(10**-(__import__(\"math\").factorial(n)) for n in range(1, 8))\nprint(f\"  Σ 10^(-n!) ≈ {L:.12f} (approximated too well by rationals -> transcendental)\")\n"}, {"tier": "Advanced", "g": "Geometry", "title": "Arithmetic Geometry (Introduction)", "desc": "Geometry over ℤ: schemes (Spec ℤ - primes as points), varieties over finite fields (Weil conjectures - Deligne 1974, Fields medal: zeta functions of varieties), Arakelov theory (infinity as a prime), anabelian (π₁ recovers curves - Grothendieck).\nMordell conjecture (Faltings 1983, Fields: genus ≥ 2 curves have finitely many rational points); abc (Szpiro's conjecture - Mochizuki claimed); perfectoid spaces (Scholze, Fields 2018). The unification of numbers and shapes - Grothendieck's vision.", "how": "Think Spec ℤ (generic + closed points); count points mod p (Weil bounds); apply Faltings (finiteness for genus ≥ 2). Learn schemes (Hartshorne/Eisenbud-Harris) before arithmetic geometry. Follow Scholze's condensed/perfectoid program.", "keys": ["Spec ℤ: primes as points.", "Weil conjectures (Deligne 1974).", "Faltings 1983: Mordell proved.", "Arakelov: infinity as prime.", "Scholze: perfectoid (Fields 2018)."], "reqs": ["Scheme/variety defined.", "Genus stated.", "Point counts."], "stds": ["Spec notation.", "Weil bounds."], "cites": ["Faltings G. Invent Math 1983;73:349-366.", "Deligne P. (Weil II, 1980)."], "demo": "#!/usr/bin/env python3\n\"\"\"Weil bound: points on curve mod p.\"\"\"\ndef weil(p, genus):\n    return (p+1-2*genus*p**0.5, p+1+2*genus*p**0.5)\nprint(\"  genus-1 curve mod 101: points in\", tuple(f\"{v:.0f}\" for v in weil(101, 1)))\n"}, {"tier": "Advanced", "g": "Computation", "title": "Computational Number Theory", "desc": "Algorithms: primality (Miller-Rabin, ECPP), factoring (NFS - 829-bit RSA-250 factored 2020, ~2700 core-years), discrete log (index calculus), lattice reduction (LLL), class groups, point counting (Schoof-Elkies-Atkin).\nSoftware: PARI/GP, SageMath, Magma, NTL. Records: largest primes (GIMPS), π(x) (10²⁸), zeta zeros (10¹³). Complexity: factoring subexponential (NFS), quantum polynomial (Shor) - the cryptographic balance.", "how": "Choose algorithms by size (NFS for 800+ bit factoring); use PARI/Sage (never reimplement); verify records (independent implementations). Mind complexity (subexponential vs polynomial). Contribute cycles (GIMPS).", "keys": ["NFS: subexponential factoring.", "Shor: polynomial (quantum).", "PARI/GP, Sage, Magma.", "GIMPS finds primes.", "Never reimplement crypto."], "reqs": ["Algorithm + complexity.", "Size regime.", "Software named."], "stds": ["Bit sizes.", "Core-years for records."], "cites": ["Lenstra AK et al. (NFS).", "Bressoud DM. Factorization and Primality Testing. Springer; 1989."], "demo": "#!/usr/bin/env python3\n\"\"\"Pollard rho factoring (small demo).\"\"\"\ndef rho(n):\n    import math\n    if n % 2 == 0: return 2\n    for c in range(1, 20):\n        x = y = 2\n        f = lambda v: (v*v+c) % n\n        d = 1\n        while d == 1:\n            x, y = f(x), f(f(y))\n            d = math.gcd(abs(x-y), n)\n        if d != n: return d\n    return n\nprint(\"  factor of 8051:\", rho(8051), \"(83 x 97)\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-NUMTHS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-NUMTHS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-number-theory-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('number-theory-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
